#pragma once
#define BATTERIES_ALLOCATOR_HPP

#include <batteries/config.hpp>
//
#include <batteries/atomic_clamp.hpp>
#include <batteries/int_types.hpp>
#include <batteries/operators.hpp>
#include <batteries/type_traits.hpp>

#include <atomic>

namespace batt {

struct AtomicMemoryStats {
    std::atomic<usize> bytes_allocated = 0;
    std::atomic<usize> bytes_freed = 0;
    std::atomic<usize> max_usage = 0;

    //+++++++++++-+-+--+----- --- -- -  -  -   -

    void notify_alloc(usize n_bytes) noexcept
    {
        const usize observed_free = this->bytes_freed.load();
        const usize observed_alloc = this->bytes_allocated.fetch_add(n_bytes) + n_bytes;
        atomic_clamp_min(this->max_usage, observed_alloc - observed_free);
    }

    void notify_free(usize n_bytes) noexcept
    {
        this->bytes_freed.fetch_add(n_bytes);
    }

    usize usage() const noexcept
    {
        const usize observed_free = this->bytes_freed.load();
        const usize observed_alloc = this->bytes_allocated.load();
        return observed_alloc - observed_free;
    }
};

BATT_OBJECT_PRINT_IMPL((inline), AtomicMemoryStats, (bytes_allocated, bytes_freed, max_usage, usage()))

struct MemoryStats {
    usize bytes_allocated = 0;
    usize bytes_freed = 0;
    usize max_usage = 0;

    //+++++++++++-+-+--+----- --- -- -  -  -   -

    void notify_alloc(usize n_bytes) noexcept
    {
        this->bytes_allocated += n_bytes;
        this->max_usage = std::max(this->max_usage, this->usage());
    }

    void notify_free(usize n_bytes) noexcept
    {
        this->bytes_freed += n_bytes;
    }

    usize usage() const noexcept
    {
        return this->bytes_allocated - this->bytes_freed;
    }
};

BATT_OBJECT_PRINT_IMPL((inline), MemoryStats, (bytes_allocated, bytes_freed, max_usage, usage()))


template <typename BaseAllocT, bool kAtomic = true>
class StatsAllocator
{
   public:
    template <typename OtherBaseT, bool>
    friend class StatsAllocator;

    using Self = StatsAllocator;

    using Stats = std::conditional_t<kAtomic, AtomicMemoryStats, MemoryStats>;

    template <typename T>
    struct rebind {
        using other =
            StatsAllocator<typename std::allocator_traits<BaseAllocT>::template rebind_alloc<T>, kAtomic>;
    };

    //----- --- -- -  -  -   -

    using value_type = typename BaseAllocT::value_type;
    using size_type = typename BaseAllocT::size_type;
    using pointer = value_type*;

    //+++++++++++-+-+--+----- --- -- -  -  -   -

    StatsAllocator() = default;
    ~StatsAllocator() = default;

    template <typename... Args, typename = EnableIfNoShadow<Self, Args...>>
    explicit StatsAllocator(Args&&... args) noexcept : base_(BATT_FORWARD(args)...)
                                                     , stats_{}
    {
    }

    template <typename OtherBaseT>
    explicit StatsAllocator(const StatsAllocator<OtherBaseT, kAtomic>& other) noexcept
        : base_{other.base_}
        , stats_{other.stats_}
    {
    }

    template <typename OtherBaseT>
    explicit StatsAllocator(StatsAllocator<OtherBaseT, kAtomic>& other) noexcept
        : base_{other.base_}
        , stats_{other.stats_}
    {
    }

    template <typename OtherBaseT>
    explicit StatsAllocator(StatsAllocator<OtherBaseT, kAtomic>&& other) noexcept
        : base_{std::move(other.base_)}
        , stats_{std::move(other.stats_)}
    {
    }

    template <typename OtherBaseT>
    explicit StatsAllocator(const StatsAllocator<OtherBaseT, kAtomic>&& other) noexcept
        : base_{std::move(other.base_)}
        , stats_{std::move(other.stats_)}
    {
    }

    //+++++++++++-+-+--+----- --- -- -  -  -   -

    const Stats& stats() const noexcept
    {
        return *this->stats_;
    }

    const std::shared_ptr<Stats>& shared_stats() const noexcept
    {
        return this->stats_;
    }

    value_type* allocate(size_type n_values) noexcept
    {
        this->stats_->notify_alloc(n_values * sizeof(value_type));
        return this->base_.allocate(n_values);
    }

    void deallocate(value_type* ptr, size_type n_values) noexcept
    {
        this->stats_->notify_free(n_values * sizeof(value_type));
        this->base_.deallocate(ptr, n_values);
    }

    template <typename OtherBaseT>
    bool operator==(const StatsAllocator<OtherBaseT, kAtomic>&) const noexcept
    {
        return true;
    }

    template <typename OtherBaseT>
    bool operator!=(const StatsAllocator<OtherBaseT, kAtomic>&) const noexcept
    {
        return false;
    }

    //+++++++++++-+-+--+----- --- -- -  -  -   -
   private:
    BaseAllocT base_;
    std::shared_ptr<Stats> stats_ = std::make_shared<Stats>();
};

}  //namespace batt
